export interface BankQuestion {
  id: string;
  technology: string;
  level: "Beginner" | "Intermediate" | "Advanced";
  text: string;
  options: string[];
  answer: number;
}

const q = (
  id: string,
  technology: string,
  level: BankQuestion["level"],
  text: string,
  options: string[],
  answer: number,
): BankQuestion => ({ id, technology, level, text, options, answer });

